_choice_domain() {
    printf '%s\n' -globalDomain NSGlobalDomain
    defaults domains 2>/dev/null | gawk 'BEGIN { RS=", " } { gsub(/^[[:space:]]+|[[:space:]]+$/, ""); if (length($0)) print }'
}

_choice_key() {
    local domain="${argc_domain:-}"
    [[ -n "$domain" ]] || return 0
    defaults read "$domain" 2>/dev/null | gawk 'match($0, /^[[:space:]]*("[^"]+"|[^=[:space:]]+)[[:space:]]*=/) { k=substr($0, RSTART, RLENGTH); sub(/=.*/, "", k); gsub(/^[[:space:]]+|[[:space:]]+$/, "", k); gsub(/^"|"$/, "", k); if (length(k)) print k }'
}
